BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "players" (
	"player_id"	INTEGER,
	"country"	TEXT,
	"platform"	TEXT,
	"acquisition_channel"	TEXT,
	"age_bracket"	TEXT,
	"signup_date"	TEXT
);
CREATE TABLE IF NOT EXISTS "purchases" (
	"purchase_id"	INTEGER,
	"player_id"	INTEGER,
	"purchase_date"	TEXT,
	"amount_eur"	REAL
);
CREATE TABLE IF NOT EXISTS "sessions" (
	"session_id"	INTEGER,
	"player_id"	INTEGER,
	"session_start"	TEXT,
	"duration_minutes"	REAL,
	"platform"	TEXT
);
COMMIT;
